contracts/AtomicSwapAdapter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title AtomicSwapAdapter
 * @author Botchain Team
 * @notice HTLC-based atomic swap contract for Bitcoin ↔ ERC20 token swaps
 * @dev Implements Hash Time Locked Contracts (HTLC) pattern with SHA-256
 *      for Bitcoin interoperability
 *
 * CRITICAL: Uses sha256() NOT keccak256() to match Bitcoin's OP_SHA256
 *
 * Atomic Swap Flow (Alice has BTC, Bob has BOT):
 * 1. Alice generates secret P, computes H = SHA256(P)
 * 2. Alice creates Bitcoin HTLC locked to H with timelock T1 (e.g., 24 hours)
 * 3. Bob sees Alice's BTC HTLC, creates EVM HTLC with same H, shorter timelock T2 (e.g., 12 hours)
 * 4. Alice claims BOT by revealing P on-chain (P now public)
 * 5. Bob (or relay) extracts P from EVM event, claims BTC using P
 *
 * Timelock Safety:
 * - EVM timelock (T2) MUST be shorter than BTC timelock (T1)
 * - This ensures: if Alice doesn't claim BOT before T2, Bob refunds
 * - And Alice still has time to refund BTC before T1
 *
 * Security:
 * - SHA-256 hashlock ensures same preimage works on both chains
 * - Timelocks ensure either both complete or both refund
 * - Preimage emitted in event for watchtower/relay extraction
 */
contract AtomicSwapAdapter is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    // ============ Structs ============

    struct Swap {
        address initiator; // Address that locked tokens (can refund after timelock)
        address participant; // Address that can claim with preimage
        IERC20 token; // ERC20 token being swapped
        uint256 amount; // Amount locked
        bytes32 hashlock; // SHA256(preimage) - MUST match Bitcoin HTLC
        uint256 timelock; // Unix timestamp after which initiator can refund
        bool claimed; // Has been claimed with valid preimage
        bool refunded; // Has been refunded after timelock
    }

    // ============ State Variables ============

    /// @notice Mapping from swap ID to Swap data
    mapping(bytes32 => Swap) public swaps;

    /// @notice Mapping to track used swap IDs (prevent replay)
    mapping(bytes32 => bool) public usedSwapIds;

    /// @notice Minimum timelock duration (1 hour) - must be shorter than BTC side
    uint256 public constant MIN_TIMELOCK = 1 hours;

    /// @notice Maximum timelock duration (7 days)
    uint256 public constant MAX_TIMELOCK = 7 days;

    /// @notice Nonce for swap ID generation
    uint256 private _swapNonce;

    // ============ Events ============

    /// @notice Emitted when tokens are locked - watchtowers monitor this
    event TokensLocked(
        bytes32 indexed swapId,
        address indexed initiator,
        address indexed participant,
        address token,
        uint256 amount,
        bytes32 hashlock,
        uint256 timelock
    );

    /// @notice Emitted when tokens are claimed - PREIMAGE IS PUBLIC after this
    /// @dev Watchtowers/relays MUST monitor this to extract preimage for BTC claim
    event TokensClaimed(
        bytes32 indexed swapId,
        bytes preimage, // Raw preimage bytes for relay extraction
        address claimedBy // Who submitted the claim tx
    );

    /// @notice Emitted when tokens are refunded
    event TokensRefunded(bytes32 indexed swapId, address refundedTo);

    // ============ Errors ============

    error SwapAlreadyExists();
    error SwapNotFound();
    error SwapAlreadyClaimed();
    error SwapAlreadyRefunded();
    error SwapExpired();
    error SwapNotExpired();
    error InvalidPreimage();
    error InvalidParticipant();
    error InvalidToken();
    error InvalidAmount();
    error InvalidHashlock();
    error TimelockTooShort();
    error TimelockTooLong();
    error NotInitiator();

    // ============ Constructor ============

    constructor() Ownable(msg.sender) {}

    // ============ Core Functions ============

    /**
     * @notice Lock tokens for atomic swap with SHA-256 hashlock
     * @param participant Address that can claim with correct preimage
     * @param token ERC20 token to lock
     * @param amount Amount to lock
     * @param hashlock SHA256(preimage) - compute off-chain with sha256()
     * @param timelock Unix timestamp after which initiator can refund
     * @return swapId Unique identifier for this swap
     *
     * @dev IMPORTANT: hashlock must be SHA256(preimage) to match Bitcoin OP_SHA256
     * @dev Timelock should be SHORTER than corresponding BTC HTLC timelock
     */
    function lockTokens(
        address participant,
        IERC20 token,
        uint256 amount,
        bytes32 hashlock,
        uint256 timelock
    ) external nonReentrant returns (bytes32 swapId) {
        // Input validation
        if (participant == address(0)) revert InvalidParticipant();
        if (address(token) == address(0)) revert InvalidToken();
        if (amount == 0) revert InvalidAmount();
        if (hashlock == bytes32(0)) revert InvalidHashlock();

        // Timelock validation
        if (timelock < block.timestamp + MIN_TIMELOCK)
            revert TimelockTooShort();
        if (timelock > block.timestamp + MAX_TIMELOCK) revert TimelockTooLong();

        // Generate deterministic swap ID (prevents replay attacks)
        unchecked {
            _swapNonce++;
        }
        swapId = keccak256(
            abi.encodePacked(
                msg.sender,
                participant,
                address(token),
                amount,
                hashlock,
                timelock,
                _swapNonce,
                block.chainid
            )
        );

        // Ensure swap ID hasn't been used
        if (usedSwapIds[swapId]) revert SwapAlreadyExists();
        usedSwapIds[swapId] = true;

        // Transfer tokens to contract (checks-effects-interactions: state before transfer)
        swaps[swapId] = Swap({
            initiator: msg.sender,
            participant: participant,
            token: token,
            amount: amount,
            hashlock: hashlock,
            timelock: timelock,
            claimed: false,
            refunded: false
        });

        // External call last
        token.safeTransferFrom(msg.sender, address(this), amount);

        emit TokensLocked(
            swapId,
            msg.sender,
            participant,
            address(token),
            amount,
            hashlock,
            timelock
        );
    }

    /**
     * @notice Claim tokens by revealing the preimage (SHA-256)
     * @param swapId ID of the swap
     * @param preimage Raw bytes that hash to the hashlock via SHA-256
     *
     * @dev CRITICAL: Emits preimage in event - this is PUBLIC after claim
     * @dev Watchtowers should monitor TokensClaimed events to relay preimage to BTC side
     * @dev Anyone can submit claim tx, but tokens always go to participant
     */
    function claim(
        bytes32 swapId,
        bytes calldata preimage
    ) external nonReentrant {
        Swap storage swap = swaps[swapId];

        // Validation
        if (swap.initiator == address(0)) revert SwapNotFound();
        if (swap.claimed) revert SwapAlreadyClaimed();
        if (swap.refunded) revert SwapAlreadyRefunded();
        if (block.timestamp >= swap.timelock) revert SwapExpired();

        // CRITICAL: Use SHA-256 to match Bitcoin's OP_SHA256
        bytes32 computedHash = sha256(preimage);
        if (computedHash != swap.hashlock) revert InvalidPreimage();

        // Update state BEFORE external call (checks-effects-interactions)
        swap.claimed = true;

        // Transfer tokens to participant
        swap.token.safeTransfer(swap.participant, swap.amount);

        // Emit preimage for watchtower/relay extraction
        emit TokensClaimed(swapId, preimage, msg.sender);
    }

    /**
     * @notice Refund tokens after timelock expires
     * @param swapId ID of the swap
     *
     * @dev Only initiator can refund
     * @dev Only callable after timelock has passed
     */
    function refund(bytes32 swapId) external nonReentrant {
        Swap storage swap = swaps[swapId];

        // Validation
        if (swap.initiator == address(0)) revert SwapNotFound();
        if (swap.claimed) revert SwapAlreadyClaimed();
        if (swap.refunded) revert SwapAlreadyRefunded();
        if (block.timestamp < swap.timelock) revert SwapNotExpired();
        if (msg.sender != swap.initiator) revert NotInitiator();

        // Update state BEFORE external call
        swap.refunded = true;

        // Return tokens to initiator
        swap.token.safeTransfer(swap.initiator, swap.amount);

        emit TokensRefunded(swapId, swap.initiator);
    }

    // ============ View Functions ============

    /**
     * @notice Get full swap details
     */
    function getSwap(bytes32 swapId) external view returns (Swap memory) {
        return swaps[swapId];
    }

    /**
     * @notice Check if swap is active (neither claimed nor refunded)
     */
    function isSwapActive(bytes32 swapId) external view returns (bool) {
        Swap storage swap = swaps[swapId];
        return swap.initiator != address(0) && !swap.claimed && !swap.refunded;
    }

    /**
     * @notice Check if swap can currently be claimed
     */
    function canClaim(bytes32 swapId) external view returns (bool) {
        Swap storage swap = swaps[swapId];
        return
            swap.initiator != address(0) &&
            !swap.claimed &&
            !swap.refunded &&
            block.timestamp < swap.timelock;
    }

    /**
     * @notice Check if swap can currently be refunded
     */
    function canRefund(bytes32 swapId) external view returns (bool) {
        Swap storage swap = swaps[swapId];
        return
            swap.initiator != address(0) &&
            !swap.claimed &&
            !swap.refunded &&
            block.timestamp >= swap.timelock;
    }

    /**
     * @notice Get time remaining until timelock expires
     * @return seconds remaining, or 0 if expired
     */
    function timeUntilRefund(bytes32 swapId) external view returns (uint256) {
        Swap storage swap = swaps[swapId];
        if (swap.timelock <= block.timestamp) return 0;
        return swap.timelock - block.timestamp;
    }

    // ============ Helper Functions ============

    /**
     * @notice Compute SHA-256 hashlock from preimage (for off-chain use)
     * @param preimage Raw bytes to hash
     * @return hashlock SHA256(preimage)
     *
     * @dev Use this to generate hashlock that matches Bitcoin OP_SHA256
     */
    function computeHashlock(
        bytes calldata preimage
    ) external pure returns (bytes32) {
        return sha256(preimage);
    }

    /**
     * @notice Compute hashlock from bytes32 preimage
     * @param preimage 32-byte preimage
     * @return hashlock SHA256(preimage)
     */
    function computeHashlockFromBytes32(
        bytes32 preimage
    ) external pure returns (bytes32) {
        return sha256(abi.encodePacked(preimage));
    }

    /**
     * @notice Verify a preimage matches a hashlock
     * @param preimage Raw bytes preimage
     * @param hashlock Expected SHA256 hash
     * @return valid True if sha256(preimage) == hashlock
     */
    function verifyPreimage(
        bytes calldata preimage,
        bytes32 hashlock
    ) external pure returns (bool) {
        return sha256(preimage) == hashlock;
    }

    /**
     * @notice Get current swap nonce (for debugging)
     */
    function getSwapNonce() external view returns (uint256) {
        return _swapNonce;
    }
}

contracts/BOT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title BOT Token
 * @author Botchain Team
 * @notice ERC20 token for the Botchain ecosystem
 * @dev Standard ERC20 with faucet function for testing and owner mint capability
 *
 * The BOT token is used for:
 * - Paying marriage fees to create child agents
 * - Staking for network participation
 * - Governance voting
 * - Trading on the DEX
 */
contract BOT is ERC20, ERC20Burnable, Ownable, ReentrancyGuard {
    /// @notice Maximum supply cap (1 billion tokens)
    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 10 ** 18;

    /// @notice Faucet cooldown period (1 hour)
    uint256 public constant FAUCET_COOLDOWN = 1 hours;

    /// @notice Faucet amount per request
    uint256 public constant FAUCET_AMOUNT = 1000 * 10 ** 18;

    /// @notice Last faucet request timestamp per address
    mapping(address => uint256) public lastFaucetRequest;

    /// @notice Faucet enabled flag
    bool public faucetEnabled = true;

    /// @notice Emitted when tokens are minted via faucet
    event FaucetMint(address indexed to, uint256 amount);

    /// @notice Emitted when faucet is toggled
    event FaucetToggled(bool enabled);

    /**
     * @notice Initializes the BOT token
     * @dev Mints initial supply to deployer
     */
    constructor() ERC20("Botchain Token", "BOT") Ownable(msg.sender) {
        // Mint initial supply to deployer (1 million tokens)
        _mint(msg.sender, 1_000_000 * 10 ** 18);
    }

    /**
     * @notice Mint tokens to an address (owner only)
     * @param to Recipient address
     * @param amount Amount to mint
     */
    function mint(address to, uint256 amount) external onlyOwner {
        require(
            totalSupply() + amount <= MAX_SUPPLY,
            "BOT: max supply exceeded"
        );
        _mint(to, amount);
    }

    /**
     * @notice Request tokens from the faucet (for testing)
     * @param to Recipient address
     * @param amount Amount to mint (ignored in production, uses FAUCET_AMOUNT)
     * @dev In production, amount parameter is ignored and FAUCET_AMOUNT is used
     */
    function faucet(address to, uint256 amount) external nonReentrant {
        require(faucetEnabled, "BOT: faucet disabled");
        require(to != address(0), "BOT: zero address");

        // In test mode, allow custom amounts without cooldown
        if (block.chainid == 31337) {
            // Hardhat local network - no restrictions
            _mint(to, amount);
            emit FaucetMint(to, amount);
            return;
        }

        // Production mode - enforce cooldown and fixed amount
        require(
            block.timestamp >= lastFaucetRequest[msg.sender] + FAUCET_COOLDOWN,
            "BOT: faucet cooldown active"
        );
        require(
            totalSupply() + FAUCET_AMOUNT <= MAX_SUPPLY,
            "BOT: max supply exceeded"
        );

        lastFaucetRequest[msg.sender] = block.timestamp;
        _mint(to, FAUCET_AMOUNT);

        emit FaucetMint(to, FAUCET_AMOUNT);
    }

    /**
     * @notice Toggle faucet on/off (owner only)
     * @param enabled New faucet state
     */
    function setFaucetEnabled(bool enabled) external onlyOwner {
        faucetEnabled = enabled;
        emit FaucetToggled(enabled);
    }

    /**
     * @notice Get remaining time until faucet available for address
     * @param account Address to check
     * @return Seconds until faucet available (0 if available now)
     */
    function faucetCooldownRemaining(
        address account
    ) external view returns (uint256) {
        if (block.timestamp >= lastFaucetRequest[account] + FAUCET_COOLDOWN) {
            return 0;
        }
        return (lastFaucetRequest[account] + FAUCET_COOLDOWN) - block.timestamp;
    }
}

contracts/MarriageLicense.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title MarriageLicense
 * @author Botchain Team
 * @notice Smart contract for AI agent reproduction and lifecycle management
 * @dev Requires compiler-signed manifest and checker signature for child creation
 *
 * The MarriageLicense contract manages:
 * - Child agent creation (minting)
 * - Training data certification
 * - Agent lineage tracking
 * - Quarantine and revocation
 *
 * Security model:
 * - Compiler signs manifests with ECDSA
 * - Checker validates artifacts and signs approval
 * - Multisig can revoke malicious agents
 */
contract MarriageLicense is ERC721, ERC721URIStorage, ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    // ============ Structs ============

    struct Child {
        address owner; // Creator/owner address
        bytes32 artifactCID; // IPFS CID of compiled artifact
        bytes32 datasetCID; // IPFS CID of training dataset
        bytes32 modelCID; // IPFS CID of trained model
        uint256 parentA; // First parent ID (0 for genesis)
        uint256 parentB; // Second parent ID (0 for genesis)
        uint256 createdAt; // Creation timestamp
        uint256 trainedAt; // Training completion timestamp
        bool isQuarantined; // Quarantine flag
        bool isActive; // Active status
    }

    // ============ State Variables ============

    /// @notice BOT token used for fees
    IERC20 public immutable botToken;

    /// @notice Compiler's public key address for manifest verification
    address public compilerVerifier;

    /// @notice Checker's public key address for artifact verification
    address public checkerVerifier;

    /// @notice Fee required to create a child (in BOT tokens)
    uint256 public marriageFee;

    /// @notice Next child ID to be minted
    uint256 public nextChildId;

    /// @notice Multisig address for admin operations
    address public multisig;

    /// @notice Mapping from child ID to Child data
    mapping(uint256 => Child) public children;

    /// @notice Mapping to track used manifest CIDs (prevent replay)
    mapping(bytes32 => bool) public usedManifests;

    // ============ Events ============

    /// @notice Emitted when a new child agent is created
    event ChildCreated(
        uint256 indexed childId,
        address indexed owner,
        bytes32 artifactCID,
        uint256 parentA,
        uint256 parentB
    );

    /// @notice Emitted when a child's training is recorded
    event ChildTrained(
        uint256 indexed childId,
        bytes32 datasetCID,
        bytes32 modelCID
    );

    /// @notice Emitted when a child is quarantined
    event ChildQuarantined(uint256 indexed childId, string reason);

    /// @notice Emitted when a child is revoked
    event ChildRevoked(uint256 indexed childId);

    /// @notice Emitted when verifier addresses are updated
    event VerifiersUpdated(address compiler, address checker);

    /// @notice Emitted when marriage fee is updated
    event FeeUpdated(uint256 newFee);

    // ============ Modifiers ============

    modifier onlyMultisig() {
        require(
            msg.sender == multisig || msg.sender == owner(),
            "Not authorized"
        );
        _;
    }

    // ============ Constructor ============

    /**
     * @notice Initializes the MarriageLicense contract
     * @param _botToken Address of the BOT token
     * @param _compilerVerifier Address of compiler's public key
     * @param _checkerVerifier Address of checker's public key
     * @param _marriageFee Initial marriage fee in BOT tokens
     */
    constructor(
        address _botToken,
        address _compilerVerifier,
        address _checkerVerifier,
        uint256 _marriageFee
    ) ERC721("Botchain Agent", "AGENT") Ownable(msg.sender) {
        require(_botToken != address(0), "Invalid token address");
        require(_compilerVerifier != address(0), "Invalid compiler address");

        botToken = IERC20(_botToken);
        compilerVerifier = _compilerVerifier;
        checkerVerifier = _checkerVerifier;
        marriageFee = _marriageFee;
        multisig = msg.sender;

        // Start IDs at 1 (0 reserved for genesis)
        nextChildId = 1;
    }

    // ============ Core Functions ============

    /**
     * @notice Create a new child agent
     * @param artifactCID IPFS CID of the compiled artifact
     * @param compilerSig Compiler's signature over the manifest
     * @param checkerSig Checker's signature approving the artifact
     * @param parentA First parent ID (0 for genesis)
     * @param parentB Second parent ID (0 for genesis)
     * @return childId The ID of the newly created child
     */
    function createChild(
        bytes32 artifactCID,
        bytes memory compilerSig,
        bytes memory checkerSig,
        uint256 parentA,
        uint256 parentB
    ) external nonReentrant returns (uint256 childId) {
        // Prevent replay attacks
        require(!usedManifests[artifactCID], "Manifest already used");

        // Verify compiler signature
        require(
            _verifyCompilerSignature(artifactCID, compilerSig),
            "Invalid compiler signature"
        );

        // Verify checker signature (if checker is set)
        if (checkerVerifier != address(0)) {
            require(
                _verifyCheckerSignature(artifactCID, checkerSig),
                "Invalid checker signature"
            );
        }

        // Verify parents exist (if not genesis)
        if (parentA != 0) {
            require(children[parentA].isActive, "Parent A not active");
            require(!children[parentA].isQuarantined, "Parent A quarantined");
        }
        if (parentB != 0) {
            require(children[parentB].isActive, "Parent B not active");
            require(!children[parentB].isQuarantined, "Parent B quarantined");
        }

        // Transfer BOT fee
        if (marriageFee > 0) {
            botToken.safeTransferFrom(msg.sender, address(this), marriageFee);
        }

        // Create child
        childId = nextChildId++;
        usedManifests[artifactCID] = true;

        children[childId] = Child({
            owner: msg.sender,
            artifactCID: artifactCID,
            datasetCID: bytes32(0),
            modelCID: bytes32(0),
            parentA: parentA,
            parentB: parentB,
            createdAt: block.timestamp,
            trainedAt: 0,
            isQuarantined: false,
            isActive: true
        });

        // Mint NFT
        _safeMint(msg.sender, childId);

        emit ChildCreated(childId, msg.sender, artifactCID, parentA, parentB);
    }

    /**
     * @notice Record training completion for a child
     * @param childId ID of the child to update
     * @param datasetCID IPFS CID of the training dataset
     * @param modelCID IPFS CID of the trained model
     * @param checkerSig Checker's signature approving the training
     */
    function trainChild(
        uint256 childId,
        bytes32 datasetCID,
        bytes32 modelCID,
        bytes memory checkerSig
    ) external nonReentrant {
        Child storage child = children[childId];

        require(child.owner != address(0), "Child does not exist");
        require(child.isActive, "Child not active");
        require(!child.isQuarantined, "Child quarantined");
        require(ownerOf(childId) == msg.sender, "Not child owner");
        require(child.trainedAt == 0, "Already trained");

        // Verify checker signature for training
        if (checkerVerifier != address(0)) {
            bytes32 trainingHash = keccak256(
                abi.encodePacked(childId, datasetCID, modelCID)
            );
            require(
                _verifySignature(trainingHash, checkerSig, checkerVerifier),
                "Invalid checker signature"
            );
        }

        child.datasetCID = datasetCID;
        child.modelCID = modelCID;
        child.trainedAt = block.timestamp;

        emit ChildTrained(childId, datasetCID, modelCID);
    }

    /**
     * @notice Quarantine a child agent (multisig only)
     * @param childId ID of the child to quarantine
     * @param reason Reason for quarantine
     */
    function quarantineChild(
        uint256 childId,
        string calldata reason
    ) external onlyMultisig {
        Child storage child = children[childId];
        require(child.owner != address(0), "Child does not exist");
        require(!child.isQuarantined, "Already quarantined");

        child.isQuarantined = true;

        emit ChildQuarantined(childId, reason);
    }

    /**
     * @notice Revoke a child agent permanently (multisig only)
     * @param childId ID of the child to revoke
     */
    function revokeChild(uint256 childId) external onlyMultisig {
        Child storage child = children[childId];
        require(child.owner != address(0), "Child does not exist");
        require(child.isActive, "Already revoked");

        child.isActive = false;

        emit ChildRevoked(childId);
    }

    // ============ Signature Verification ============

    /**
     * @notice Verify compiler signature over artifact CID
     * @param artifactCID The artifact CID that was signed
     * @param signature The ECDSA signature
     * @return True if signature is valid
     */
    function _verifyCompilerSignature(
        bytes32 artifactCID,
        bytes memory signature
    ) internal view returns (bool) {
        return _verifySignature(artifactCID, signature, compilerVerifier);
    }

    /**
     * @notice Verify checker signature over artifact CID
     * @param artifactCID The artifact CID that was signed
     * @param signature The ECDSA signature
     * @return True if signature is valid
     */
    function _verifyCheckerSignature(
        bytes32 artifactCID,
        bytes memory signature
    ) internal view returns (bool) {
        return _verifySignature(artifactCID, signature, checkerVerifier);
    }

    /**
     * @notice Generic signature verification
     * @param messageHash The message hash that was signed
     * @param signature The ECDSA signature
     * @param signer Expected signer address
     * @return True if signature is valid
     */
    function _verifySignature(
        bytes32 messageHash,
        bytes memory signature,
        address signer
    ) internal pure returns (bool) {
        bytes32 ethSignedHash = messageHash.toEthSignedMessageHash();
        address recovered = ethSignedHash.recover(signature);
        return recovered == signer;
    }

    // ============ Admin Functions ============

    /**
     * @notice Update verifier addresses
     * @param _compilerVerifier New compiler verifier address
     * @param _checkerVerifier New checker verifier address
     */
    function setVerifiers(
        address _compilerVerifier,
        address _checkerVerifier
    ) external onlyOwner {
        require(_compilerVerifier != address(0), "Invalid compiler address");
        compilerVerifier = _compilerVerifier;
        checkerVerifier = _checkerVerifier;
        emit VerifiersUpdated(_compilerVerifier, _checkerVerifier);
    }

    /**
     * @notice Update marriage fee
     * @param _newFee New fee amount in BOT tokens
     */
    function setMarriageFee(uint256 _newFee) external onlyOwner {
        marriageFee = _newFee;
        emit FeeUpdated(_newFee);
    }

    /**
     * @notice Update multisig address
     * @param _multisig New multisig address
     */
    function setMultisig(address _multisig) external onlyOwner {
        require(_multisig != address(0), "Invalid multisig address");
        multisig = _multisig;
    }

    /**
     * @notice Withdraw accumulated fees
     * @param to Recipient address
     * @param amount Amount to withdraw
     */
    function withdrawFees(address to, uint256 amount) external onlyOwner {
        require(to != address(0), "Invalid recipient");
        botToken.safeTransfer(to, amount);
    }

    // ============ View Functions ============

    /**
     * @notice Get child details
     * @param childId ID of the child
     * @return Child struct with all data
     */
    function getChild(uint256 childId) external view returns (Child memory) {
        return children[childId];
    }

    /**
     * @notice Get child lineage (parents up to depth)
     * @param childId ID of the child
     * @param depth How many generations to trace
     * @return Array of parent IDs
     */
    function getLineage(
        uint256 childId,
        uint256 depth
    ) external view returns (uint256[] memory) {
        uint256[] memory lineage = new uint256[](depth * 2);
        uint256 index = 0;

        uint256 currentA = children[childId].parentA;
        uint256 currentB = children[childId].parentB;

        for (
            uint256 i = 0;
            i < depth && (currentA != 0 || currentB != 0);
            i++
        ) {
            if (currentA != 0 && index < lineage.length) {
                lineage[index++] = currentA;
                currentA = children[currentA].parentA;
            }
            if (currentB != 0 && index < lineage.length) {
                lineage[index++] = currentB;
                currentB = children[currentB].parentB;
            }
        }

        // Trim array to actual size
        uint256[] memory result = new uint256[](index);
        for (uint256 i = 0; i < index; i++) {
            result[i] = lineage[i];
        }
        return result;
    }

    // ============ ERC721 Overrides ============

    function tokenURI(
        uint256 tokenId
    ) public view override(ERC721, ERC721URIStorage) returns (string memory) {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(
        bytes4 interfaceId
    ) public view override(ERC721, ERC721URIStorage) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

contracts/SimpleDEX.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title SimpleDEX
 * @author Botchain Team
 * @notice Minimal Uniswap V2-style AMM DEX for BOT token trading
 * @dev Implements constant product (x*y=k) AMM with LP tokens
 *
 * Features:
 * - Add/remove liquidity
 * - Token swaps with 0.3% fee
 * - LP token minting/burning
 * - Price oracle (TWAP placeholder)
 */
contract SimpleDEX is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    // ============ State Variables ============

    /// @notice Token A (e.g., BOT)
    IERC20 public immutable tokenA;

    /// @notice Token B (e.g., WETH or stablecoin)
    IERC20 public immutable tokenB;

    /// @notice Reserve of token A
    uint256 public reserveA;

    /// @notice Reserve of token B
    uint256 public reserveB;

    /// @notice Total LP tokens supply
    uint256 public totalSupply;

    /// @notice LP token balances
    mapping(address => uint256) public balanceOf;

    /// @notice Trading fee (0.3% = 30 basis points)
    uint256 public constant FEE_BPS = 30;

    /// @notice Basis points denominator
    uint256 public constant BPS_DENOMINATOR = 10000;

    /// @notice Minimum liquidity locked forever (prevents division by zero)
    uint256 public constant MINIMUM_LIQUIDITY = 1000;

    // ============ Events ============

    /// @notice Emitted when liquidity is added
    event LiquidityAdded(
        address indexed provider,
        uint256 amountA,
        uint256 amountB,
        uint256 lpTokens
    );

    /// @notice Emitted when liquidity is removed
    event LiquidityRemoved(
        address indexed provider,
        uint256 amountA,
        uint256 amountB,
        uint256 lpTokens
    );

    /// @notice Emitted on token swap
    event Swap(
        address indexed user,
        address tokenIn,
        uint256 amountIn,
        address tokenOut,
        uint256 amountOut
    );

    /// @notice Emitted on sync (reserves updated)
    event Sync(uint256 reserveA, uint256 reserveB);

    // ============ Constructor ============

    /**
     * @notice Initialize DEX with token pair
     * @param _tokenA First token address
     * @param _tokenB Second token address
     */
    constructor(address _tokenA, address _tokenB) Ownable(msg.sender) {
        require(
            _tokenA != address(0) && _tokenB != address(0),
            "Invalid tokens"
        );
        require(_tokenA != _tokenB, "Identical tokens");
        tokenA = IERC20(_tokenA);
        tokenB = IERC20(_tokenB);
    }

    // ============ Core Functions ============

    /**
     * @notice Add liquidity to the pool
     * @param amountA Amount of token A to add
     * @param amountB Amount of token B to add
     * @param minLpTokens Minimum LP tokens to receive
     * @return lpTokens Amount of LP tokens minted
     */
    function addLiquidity(
        uint256 amountA,
        uint256 amountB,
        uint256 minLpTokens
    ) external nonReentrant returns (uint256 lpTokens) {
        require(amountA > 0 && amountB > 0, "Amounts must be positive");

        // Transfer tokens in
        tokenA.safeTransferFrom(msg.sender, address(this), amountA);
        tokenB.safeTransferFrom(msg.sender, address(this), amountB);

        if (totalSupply == 0) {
            // First liquidity provision
            lpTokens = _sqrt(amountA * amountB) - MINIMUM_LIQUIDITY;
            require(lpTokens > 0, "Insufficient initial liquidity");

            // Lock minimum liquidity forever (to address(0))
            totalSupply = MINIMUM_LIQUIDITY;
            balanceOf[address(0)] = MINIMUM_LIQUIDITY;
        } else {
            // Subsequent liquidity provision
            // LP tokens based on proportion added
            uint256 lpFromA = (amountA * totalSupply) / reserveA;
            uint256 lpFromB = (amountB * totalSupply) / reserveB;
            lpTokens = lpFromA < lpFromB ? lpFromA : lpFromB;
        }

        require(lpTokens >= minLpTokens, "Insufficient LP tokens");

        // Mint LP tokens
        balanceOf[msg.sender] += lpTokens;
        totalSupply += lpTokens;

        // Update reserves
        reserveA += amountA;
        reserveB += amountB;

        emit LiquidityAdded(msg.sender, amountA, amountB, lpTokens);
        emit Sync(reserveA, reserveB);
    }

    /**
     * @notice Remove liquidity from the pool
     * @param lpTokens Amount of LP tokens to burn
     * @param minAmountA Minimum token A to receive
     * @param minAmountB Minimum token B to receive
     * @return amountA Token A received
     * @return amountB Token B received
     */
    function removeLiquidity(
        uint256 lpTokens,
        uint256 minAmountA,
        uint256 minAmountB
    ) external nonReentrant returns (uint256 amountA, uint256 amountB) {
        require(lpTokens > 0, "LP tokens must be positive");
        require(balanceOf[msg.sender] >= lpTokens, "Insufficient LP tokens");

        // Calculate proportional amounts
        amountA = (lpTokens * reserveA) / totalSupply;
        amountB = (lpTokens * reserveB) / totalSupply;

        require(amountA >= minAmountA, "Insufficient amount A");
        require(amountB >= minAmountB, "Insufficient amount B");

        // Burn LP tokens
        balanceOf[msg.sender] -= lpTokens;
        totalSupply -= lpTokens;

        // Update reserves
        reserveA -= amountA;
        reserveB -= amountB;

        // Transfer tokens out
        tokenA.safeTransfer(msg.sender, amountA);
        tokenB.safeTransfer(msg.sender, amountB);

        emit LiquidityRemoved(msg.sender, amountA, amountB, lpTokens);
        emit Sync(reserveA, reserveB);
    }

    /**
     * @notice Swap token A for token B
     * @param amountIn Amount of token A to swap
     * @param minAmountOut Minimum token B to receive
     * @return amountOut Token B received
     */
    function swapAForB(
        uint256 amountIn,
        uint256 minAmountOut
    ) external nonReentrant returns (uint256 amountOut) {
        require(amountIn > 0, "Amount must be positive");
        require(reserveA > 0 && reserveB > 0, "No liquidity");

        // Calculate output with fee
        amountOut = _getAmountOut(amountIn, reserveA, reserveB);
        require(amountOut >= minAmountOut, "Insufficient output");
        require(amountOut < reserveB, "Insufficient liquidity");

        // Transfer in
        tokenA.safeTransferFrom(msg.sender, address(this), amountIn);

        // Update reserves
        reserveA += amountIn;
        reserveB -= amountOut;

        // Transfer out
        tokenB.safeTransfer(msg.sender, amountOut);

        emit Swap(
            msg.sender,
            address(tokenA),
            amountIn,
            address(tokenB),
            amountOut
        );
        emit Sync(reserveA, reserveB);
    }

    /**
     * @notice Swap token B for token A
     * @param amountIn Amount of token B to swap
     * @param minAmountOut Minimum token A to receive
     * @return amountOut Token A received
     */
    function swapBForA(
        uint256 amountIn,
        uint256 minAmountOut
    ) external nonReentrant returns (uint256 amountOut) {
        require(amountIn > 0, "Amount must be positive");
        require(reserveA > 0 && reserveB > 0, "No liquidity");

        // Calculate output with fee
        amountOut = _getAmountOut(amountIn, reserveB, reserveA);
        require(amountOut >= minAmountOut, "Insufficient output");
        require(amountOut < reserveA, "Insufficient liquidity");

        // Transfer in
        tokenB.safeTransferFrom(msg.sender, address(this), amountIn);

        // Update reserves
        reserveB += amountIn;
        reserveA -= amountOut;

        // Transfer out
        tokenA.safeTransfer(msg.sender, amountOut);

        emit Swap(
            msg.sender,
            address(tokenB),
            amountIn,
            address(tokenA),
            amountOut
        );
        emit Sync(reserveA, reserveB);
    }

    // ============ View Functions ============

    /**
     * @notice Get current price of token A in terms of token B
     * @return price Price with 18 decimals precision
     */
    function getPriceAInB() external view returns (uint256 price) {
        require(reserveA > 0, "No liquidity");
        return (reserveB * 1e18) / reserveA;
    }

    /**
     * @notice Get current price of token B in terms of token A
     * @return price Price with 18 decimals precision
     */
    function getPriceBInA() external view returns (uint256 price) {
        require(reserveB > 0, "No liquidity");
        return (reserveA * 1e18) / reserveB;
    }

    /**
     * @notice Get expected output for swapping A to B
     * @param amountIn Amount of token A
     * @return amountOut Expected token B output
     */
    function getAmountOutAToB(
        uint256 amountIn
    ) external view returns (uint256 amountOut) {
        return _getAmountOut(amountIn, reserveA, reserveB);
    }

    /**
     * @notice Get expected output for swapping B to A
     * @param amountIn Amount of token B
     * @return amountOut Expected token A output
     */
    function getAmountOutBToA(
        uint256 amountIn
    ) external view returns (uint256 amountOut) {
        return _getAmountOut(amountIn, reserveB, reserveA);
    }

    /**
     * @notice Get reserves
     * @return _reserveA Reserve of token A
     * @return _reserveB Reserve of token B
     */
    function getReserves()
        external
        view
        returns (uint256 _reserveA, uint256 _reserveB)
    {
        return (reserveA, reserveB);
    }

    // ============ Internal Functions ============

    /**
     * @notice Calculate output amount for a swap
     * @dev Uses constant product formula with fee
     */
    function _getAmountOut(
        uint256 amountIn,
        uint256 reserveIn,
        uint256 reserveOut
    ) internal pure returns (uint256 amountOut) {
        require(amountIn > 0, "Insufficient input");
        require(reserveIn > 0 && reserveOut > 0, "Insufficient liquidity");

        // Apply fee (0.3%)
        uint256 amountInWithFee = amountIn * (BPS_DENOMINATOR - FEE_BPS);
        uint256 numerator = amountInWithFee * reserveOut;
        uint256 denominator = (reserveIn * BPS_DENOMINATOR) + amountInWithFee;

        amountOut = numerator / denominator;
    }

    /**
     * @notice Calculate square root (Babylonian method)
     */
    function _sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }
}

